def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    W = n if n < 20 else 20
    recent = history[n-W:]

    opp_d_recent = 0
    for a, b in recent:
        if b == 'D':
            opp_d_recent += 1

    run_opp_d = 0
    for a, b in reversed(recent):
        if b == 'D':
            run_opp_d += 1
        else:
            break

    start = n - W
    if start < 1:
        start = 1

    punish_recent = 0
    unpunished_recent = 0
    unprovoked_recent = 0

    for i in range(start, n):
        prev_my = history[i-1][0]
        curr_opp = history[i][1]
        if prev_my == 'D':
            if curr_opp == 'D':
                punish_recent += 1
            else:
                unpunished_recent += 1
        elif prev_my == 'C':
            if curr_opp == 'D':
                unprovoked_recent += 1

    if n >= 8:
        if run_opp_d >= 5:
            return 'D'
        if opp_d_recent * 10 >= W * 3:
            return 'D'
        if unprovoked_recent >= 5:
            return 'D'

    opp_d_total = 0
    for a, b in history:
        if b == 'D':
            opp_d_total += 1

    punish_total = 0
    unpunished_total = 0
    for i in range(1, n):
        if history[i-1][0] == 'D':
            if history[i][1] == 'D':
                punish_total += 1
            else:
                unpunished_total += 1

    friendly = opp_d_total * 10 <= n * 3

    if punish_recent == 0 and unpunished_recent >= 2:
        return 'D'

    if unpunished_recent >= 4 and unpunished_recent > 3 * punish_recent and unprovoked_recent <= 3:
        return 'D'

    if last_opp == 'D':
        return 'C'

    if last_my == 'D':
        return 'C'

    if friendly and punish_total == 0 and unpunished_total >= 1:
        return 'D'

    if friendly and punish_total == 0 and unpunished_total == 0:
        if n == 15 or n == 25 or n == 40:
            return 'D'

    return 'C'
